  {
    "id": "start",
    "scan": [
      { "id": "hit-a", "label_id": "A", "actions": [ { "inc": "hit_count" }, { "start_timer": "process_timer" } ] },
      { "id": "approve", "label_id": "B", "guard": { "var": "hit_count", "op": ">=", "value": 1 }, "actions": [ { "set": { "var": "approved", "value": true } } ] }
