    "transitions": [
      { "id": "approved", "when": { "var": "approved", "op": "==", "value": true }, "goto": "done", "actions": [ { "outcome": { "status": "OK", "code": "CUSTOM_FLOW_COMPLETED", "effects": [ { "type": "save_db", "record_type": "custom_flow" } ] } } ] }
    ],
    "on_timer_expire": [
      { "timer": "process_timer", "actions": [ { "outcome": { "status": "TIMEOUT", "code": "CUSTOM_FLOW_TIMER_TIMEOUT", "reason": "B did not arrive in time" } } ] }
    ]
  },
  { "id": "done", "scan": [], "transitions": [] }
]
